auth.mail.invite.text:
.input {$days :number}
.match $days
one {{Vous êtes invité à rejoindre {$organization} (rôle {$role}).
Lien valable {$days} jour, à usage unique :
{$url}}}
* {{Vous êtes invité à rejoindre {$organization} (rôle {$role}).
Lien valable {$days} jours, à usage unique :
{$url}}}

auth.mail.magic.text:
.input {$minutes :number}
.match $minutes
one {{Pour vous connecter, ouvrez ce lien (valable {$minutes} minute, à usage unique) :
{$url}}}
* {{Pour vous connecter, ouvrez ce lien (valable {$minutes} minutes, à usage unique) :
{$url}}}

auth.mail.reset.text:
.input {$hours :number}
.match $hours
one {{Pour choisir un nouveau mot de passe, ouvrez ce lien (valable {$hours} heure) :
{$url}}}
* {{Pour choisir un nouveau mot de passe, ouvrez ce lien (valable {$hours} heures) :
{$url}}}
